import {
  COPY_ONLY_CLASS,
  CopyToClipboard,
  NO_COPY_CLASS,
} from "@hunt/copy-to-clipboard";
import { InfoTooltip } from "@hunt/shadcn";
import { cn } from "@hunt/styled-ui";
import { type ParsedQs } from "qs";
import React, { useState, useMemo, useEffect } from "react";
import { ErratumIcon } from "../../../components/ErratumIcon";
import { updateQueryParam } from "../../../rounds/query_param_utils";
import GachaBannerSelector from "./components/GachaBannerSelector";
import GachaPageHeader from "./components/GachaPageHeader";
import {
  CASINO_BACKGROUND_STYLE,
  GOLD_BACKGROUND_STYLING,
} from "./gacha_styling";
import type { CasinoStateWithUI } from "./types";
import useGachaQueryParams, { GACHA_QUERY_KEYS } from "./useGachaQueryParam";

export type CluePullEvent = {
  type: string;
  bannerSlug: string;
  timestamp: string; // ISO string
  clueId: string;
  eventNumber: number;
};

export type ShellPullEvent = {
  type: "shell";
  bannerSlug: string;
  puzzleSlug: string;
  puzzleTitle: string;
  timestamp: string; // ISO string
  eventNumber: number;
};

type PullHistoryProps = {
  // Sorted by timestamp, increasing
  events: (CluePullEvent | ShellPullEvent)[];
  queryParams?: ParsedQs | URLSearchParams;
  state: CasinoStateWithUI;
};

// Helper to format date
function formatDate(date: Date) {
  return date.toLocaleString();
}

// Helper to get display type
function getDisplayType(event: CluePullEvent | ShellPullEvent) {
  if (event.type === "clue") {
    return "Clue";
  } else if (event.type === "shell") {
    return "Shell";
  } else {
    return "???";
  }
}

// Compute the set of clueIds that are "new" (i.e., the first time each clue appears by earliest timestamp)
function getNewEventNumbers(events: (CluePullEvent | ShellPullEvent)[]) {
  // Only consider clue events
  const clueEvents = events.filter(
    (e): e is CluePullEvent => e.type.includes("clue") && "clueId" in e,
  );
  // Map from clueId to earliest timestamp
  const clueEarliest: Record<string, number> = {};
  for (const e of clueEvents) {
    if (!(e.clueId in clueEarliest) || e.eventNumber < clueEarliest[e.clueId]) {
      clueEarliest[e.clueId] = e.eventNumber;
    }
  }
  // Set of event numbers that are "new" (i.e., the event with the lowest event number for that clueId)
  const newClueKeySet = new Set<number>();
  for (const e of clueEvents) {
    if (e.eventNumber === clueEarliest[e.clueId]) {
      newClueKeySet.add(e.eventNumber);
    }
  }
  return newClueKeySet;
}

const PAGE_SIZE = 5;

const PullHistoryTable: React.FC<{
  // pre-sorted by timestamp ascending
  events: (CluePullEvent | ShellPullEvent)[];
  selectedBanner: string;
}> = ({ events, selectedBanner }) => {
  const [page, setPage] = useState(0);
  const [inputValue, setInputValue] = useState((page + 1).toString());
  // Only allow sorting by pull number (i.e., order in original events array)
  // We'll use "pullNumber" as the only sort key
  type SortDirection = "asc" | "desc";
  const [sortDirection, setSortDirection] = useState<SortDirection>("desc");

  useEffect(() => {
    setPage(0);
    setInputValue("1");
  }, [selectedBanner]);

  useEffect(() => {
    setInputValue((page + 1).toString());
  }, [page]);

  // Memoize sorted events
  // Pull number is 1-based index in chronological order (earliest first)
  // So, we sort by timestamp ascending for pullNumber=1,2,3...
  // If sortDirection is "desc", we reverse the order
  const sortedEvents = useMemo(() => {
    return sortDirection === "asc" ? events : [...events].reverse();
  }, [events, sortDirection]);

  // Memoize the set of "new" clue event keys
  const newClueKeySet = useMemo(() => getNewEventNumbers(events), [events]);

  const pageCount = Math.ceil(sortedEvents.length / PAGE_SIZE);
  const pagedEvents = sortedEvents.slice(
    page * PAGE_SIZE,
    (page + 1) * PAGE_SIZE,
  );

  function handleSort() {
    setSortDirection((d) => (d === "asc" ? "desc" : "asc"));
    setPage(0);
  }

  function handlePageInput(inputElement: HTMLInputElement) {
    const value = inputElement.value;
    if (value === "") {
      inputElement.value = (page + 1).toString();
      return;
    }
    const newPage = parseInt(value) - 1;
    if (!isNaN(newPage) && newPage >= 0 && newPage < pageCount) {
      setPage(newPage);
    } else {
      inputElement.value = (page + 1).toString();
    }
  }

  // Compute pull numbers for the current sortedEvents
  // Map: eventKey -> pullNumber (1-based)
  const pullNumberMap = useMemo(() => {
    const map = new Map<number, number>();
    // Always assign pull numbers by timestamp ascending
    const chronological = [...events].sort(
      (a, b) =>
        new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime(),
    );
    chronological.forEach((event, idx) => {
      map.set(event.eventNumber, idx + 1);
    });
    return map;
  }, [events]);

  return (
    <>
      {/* Visible paginated table */}
      <div className={cn(NO_COPY_CLASS, "overflow-x-auto w-full")}>
        <table className="w-full border border-cash-dark-brown table-fixed">
          <colgroup>
            <col className="w-[10%]" />
            <col className="w-[30%]" />
            <col className="w-[15%]" />
            <col className="w-[45%]" />
          </colgroup>
          <thead className="bg-cash-dark-brown text-white">
            <tr>
              <th
                className="cursor-pointer p-2 border-b border-cash-dark-brown text-center"
                onClick={() => {
                  handleSort();
                }}
              >
                #{sortDirection === "asc" ? " ▲" : " ▼"}
              </th>
              <th className="p-2 border-b border-cash-dark-brown text-center">
                Timestamp
              </th>
              <th className="p-2 border-b border-cash-dark-brown text-center">
                Type
              </th>
              <th className="p-2 border-b border-cash-dark-brown">
                <div className="flex items-center justify-center gap-2">
                  Clue Unique ID
                  <InfoTooltip
                    tooltip="The Clue Unique ID is for convenience and is not a puzzle."
                    width={18}
                  />
                </div>
              </th>
            </tr>
          </thead>
          <tbody>
            {pagedEvents.length === 0 ? (
              <tr>
                <td colSpan={4} className="text-center py-4">
                  No pulls yet.
                </td>
              </tr>
            ) : (
              pagedEvents.map((event, _idx) => {
                let nameCell;
                if (event.type.includes("clue") && "clueId" in event) {
                  const isNew = newClueKeySet.has(event.eventNumber);
                  nameCell = (
                    <span className="inline-flex items-center gap-2">
                      {isNew && (
                        <span className="text-green-600 font-semibold mr-1">
                          (new!)
                        </span>
                      )}
                      <a
                        href={`/rounds/fates_thread_casino/clue/${event.clueId}`}
                      >
                        {event.clueId}
                      </a>
                      <ErratumIcon
                        resource={{ type: "clue", slug: event.clueId }}
                        iconClassName="h-4 w-4"
                      />
                    </span>
                  );
                } else {
                  const puzzleSlug = (event as ShellPullEvent).puzzleSlug;
                  const puzzleTitle = (event as ShellPullEvent).puzzleTitle;
                  nameCell = (
                    <span className="inline-flex items-center gap-2">
                      <a href={`/puzzles/${puzzleSlug}`}>{puzzleTitle}</a>
                      <ErratumIcon
                        resource={{ type: "puzzle", slug: puzzleSlug }}
                        iconClassName="h-4 w-4"
                      />
                    </span>
                  );
                }
                // Get pull number from map
                const pullNumber = pullNumberMap.get(event.eventNumber);
                return (
                  <tr key={event.eventNumber}>
                    <td className="p-2 border-b border-cash-dark-brown text-center">
                      {pullNumber}
                    </td>
                    <td className="p-2 border-b border-cash-dark-brown text-center">
                      {formatDate(new Date(event.timestamp))}
                    </td>
                    <td className="p-2 border-b border-cash-dark-brown text-center capitalize">
                      {getDisplayType(event)}
                    </td>
                    <td className="p-2 border-b border-cash-dark-brown">
                      {nameCell}
                    </td>
                  </tr>
                );
              })
            )}
          </tbody>
        </table>
        <div className="flex items-center justify-between mt-2">
          <button
            className="px-3 py-1 border rounded-lg bg-white hover:bg-gray-200 disabled:hover:bg-white disabled:opacity-50 disabled:cursor-not-allowed"
            onClick={() => {
              setPage((p) => Math.max(0, p - 1));
            }}
            disabled={page === 0}
          >
            Previous
          </button>
          <div className="flex items-center gap-2">
            <span>Page</span>
            <input
              id="page-input"
              type="number"
              aria-label="Current page number"
              min="1"
              max={pageCount === 0 ? 1 : pageCount}
              value={inputValue}
              onChange={(e) => {
                setInputValue(e.target.value);
              }}
              onBlur={(e) => {
                handlePageInput(e.target as HTMLInputElement);
              }}
              onKeyDown={(e) => {
                if (e.key === "Enter") {
                  handlePageInput(e.target as HTMLInputElement);
                }
              }}
              className="w-16 px-1 py-1 border rounded text-center text-sm"
            />
            <span>of {pageCount === 0 ? 1 : pageCount}</span>
          </div>
          <button
            className="px-3 py-1 border rounded-lg bg-white hover:bg-gray-200 disabled:hover:bg-white disabled:opacity-50 disabled:cursor-not-allowed"
            onClick={() => {
              setPage((p) => Math.min(pageCount - 1, p + 1));
            }}
            disabled={page >= pageCount - 1}
          >
            Next
          </button>
        </div>
      </div>
      {/* Copy-only table for clipboard: unpaginated, always ascending order */}
      <div className={COPY_ONLY_CLASS}>
        <table>
          <colgroup>
            <col className="w-[10%]" />
            <col className="w-[30%]" />
            <col className="w-[15%]" />
            <col className="w-[45%]" />
          </colgroup>
          <thead>
            <tr>
              <th
                className="p-2 border-b text-center"
                aria-sort={sortDirection === "asc" ? "ascending" : "descending"}
              >
                #
              </th>
              <th className="p-2 border-b text-center">Timestamp</th>
              <th className="p-2 border-b text-center">Type</th>
              <th className="p-2 border-b">Name</th>
            </tr>
          </thead>
          <tbody>
            {(() => {
              // Always sort ascending for copy table
              if (events.length === 0) {
                return (
                  <tr>
                    <td colSpan={4} className="text-center py-4">
                      No pulls yet.
                    </td>
                  </tr>
                );
              }
              return events.map((event) => {
                let pullCell;
                if (event.type.includes("clue") && "clueId" in event) {
                  pullCell = (
                    <a
                      href={`/rounds/fates_thread_casino/clue/${event.clueId}`}
                    >
                      {event.clueId}
                    </a>
                  );
                } else {
                  pullCell = (
                    <a
                      href={`/puzzles/${(event as ShellPullEvent).puzzleSlug}`}
                    >
                      shell
                    </a>
                  );
                }
                // Get pull number from map
                const pullNumber = pullNumberMap.get(event.eventNumber);
                return (
                  <tr key={event.eventNumber}>
                    <td className="p-2 border-b text-center">{pullNumber}</td>
                    <td className="p-2 border-b text-center">
                      {formatDate(new Date(event.timestamp))}
                    </td>
                    <td className="p-2 border-b text-center capitalize">
                      {getDisplayType(event)}
                    </td>
                    <td className="p-2 border-b">{pullCell}</td>
                  </tr>
                );
              });
            })()}
          </tbody>
        </table>
      </div>
    </>
  );
};

export default function PullHistory({
  events,
  queryParams,
  state,
}: PullHistoryProps) {
  // Banner select state
  const { banner } = useGachaQueryParams(queryParams);
  const [selectedBanner, setSelectedBanner] = useState(banner ?? "");
  const [numChips, setNumChips] = useState(state.available_pulls ?? 0);

  useEffect(() => {
    setNumChips(state.available_pulls ?? 0);
  }, [state.available_pulls]);

  useEffect(() => {
    if (selectedBanner) {
      updateQueryParam(GACHA_QUERY_KEYS.BANNER, selectedBanner);
    } else {
      // If no banner is selected, default to the first unlocked one.
      const unlockedBanners = state.banners.filter(
        (banner) => banner.state === "unlocked",
      );
      if (unlockedBanners.length > 0) {
        const firstBannerSlug = unlockedBanners[0].slug;
        setSelectedBanner(firstBannerSlug);
        updateQueryParam(GACHA_QUERY_KEYS.BANNER, firstBannerSlug);
      }
    }
  }, [selectedBanner, state.banners]);

  return (
    <div
      className="flex flex-col min-h-screen pt-16 w-full pb-8 overflow-x-auto"
      style={CASINO_BACKGROUND_STYLE}
    >
      <div className="flex flex-col items-center min-w-[660px] mx-auto px-8">
        <GachaPageHeader
          title="Pull History"
          selectedBanner={selectedBanner}
          numChips={numChips}
          className="min-w-[660px]"
        >
          <GachaBannerSelector
            selectedBanner={selectedBanner}
            onBannerChange={setSelectedBanner}
            state={state}
          />
        </GachaPageHeader>
        <div
          id="fates-thread-casino-pull-history-content"
          className="fates-thread-casino-pull-history-content mb-2 w-[90vw] min-w-[660px] max-w-5xl"
        >
          <div
            className={cn(
              "rounded-lg p-4 pb-4 text-black relative",
              GOLD_BACKGROUND_STYLING,
            )}
          >
            <div id="pull-history-content" className="pull-history-content">
              <PullHistoryTable
                events={events.filter((e) => e.bannerSlug === selectedBanner)}
                selectedBanner={selectedBanner ?? ""}
              />
            </div>
            <CopyToClipboard
              contentId="pull-history-content"
              variant="custom"
              className="absolute -bottom-2 right-0 translate-y-full"
              tooltipBeforeCopy="Click to copy this banner's pull history for ease of pasting into Google Sheets or Excel."
            />
          </div>
        </div>
      </div>
    </div>
  );
}
