import { type TeamHuntState } from "@hunt/public-client";
import React, { useEffect, useState } from "react";
import { hydrateRoot } from "react-dom/client";
import { useSolvedPuzzlesState } from "../components/puzzleSolveLocalState";
import PullHistory, {
  type CluePullEvent,
  type ShellPullEvent,
} from "../rounds/dimensions/gacha/PullHistory";
import { mergeCasinoState } from "../rounds/dimensions/gacha/clientUtils";
import {
  buildLocalCasinoState,
  buildLocalPullHistoryEvents,
} from "../rounds/dimensions/gacha/gachaLocalState";
import type { CasinoStateWithUI } from "../rounds/dimensions/gacha/types";
import { useGachaLocalState } from "../rounds/dimensions/gacha/useGachaLocalState";
import { IS_STATIC_SITE } from "../utils/staticSite";
import { ErrataDataProvider } from "./ErrataProvider";
import useDataset from "./useDataset";

const GachaPullHistoryManager = ({
  initialState,
  queryParams,
  initialCasinoState,
  initialTeamState,
}: {
  initialState: (CluePullEvent | ShellPullEvent)[];
  queryParams: URLSearchParams;
  initialCasinoState: CasinoStateWithUI;
  initialTeamState: TeamHuntState;
}) => {
  const isStaticSite = IS_STATIC_SITE;
  const wsState = useDataset("fates_thread_casino", undefined, {
    epoch: initialCasinoState.epoch,
    available_pulls: initialCasinoState.available_pulls,
    num_solves: initialCasinoState.num_solves,
    banner_progress: initialCasinoState.banner_progress,
  });
  const teamState = useDataset("team_state", undefined, initialTeamState);

  const [state, setState] = useState<CasinoStateWithUI>(initialCasinoState);
  const [events, setEvents] =
    useState<(CluePullEvent | ShellPullEvent)[]>(initialState);
  const { solvedMap } = useSolvedPuzzlesState();
  const { localState } = useGachaLocalState();

  useEffect(() => {
    if (isStaticSite) return;
    setState((currentState) => mergeCasinoState(wsState, currentState));
  }, [isStaticSite, wsState]);

  useEffect(() => {
    if (!isStaticSite || !localState) return;
    const nextState = buildLocalCasinoState({
      teamState,
      localState,
      solvedMap,
    });
    setState(nextState);
    setEvents(buildLocalPullHistoryEvents(localState));
  }, [isStaticSite, localState, solvedMap, teamState]);

  return (
    <ErrataDataProvider initialTeamState={initialTeamState}>
      <PullHistory events={events} queryParams={queryParams} state={state} />
    </ErrataDataProvider>
  );
};

const gachaPullHistoryElem = document.getElementById(
  "fates-thread-casino-pull-history-root",
);
if (gachaPullHistoryElem) {
  const { initialPullHistory, initialCasinoState, initialTeamState } =
    window as unknown as {
      initialPullHistory: (CluePullEvent | ShellPullEvent)[];
      initialCasinoState: CasinoStateWithUI;
      initialTeamState: TeamHuntState;
    };
  const queryParams = new URLSearchParams(window.location.search);
  hydrateRoot(
    gachaPullHistoryElem,
    <GachaPullHistoryManager
      initialState={initialPullHistory}
      queryParams={queryParams}
      initialCasinoState={initialCasinoState}
      initialTeamState={initialTeamState}
    />,
  );
} else {
  console.error(
    "Couldn't mount Fate's Thread Casino PullHistory because #fates-thread-casino-pull-history-root was nowhere to be found",
  );
}
